import{_ as t,o as s,c as a,a0 as i}from"./chunks/framework.D4fUSYzX.js";const k=JSON.parse('{"title":"Minimal Config","description":"The config file paths, the shipped defaults, a working ticket source, and how to extend the workflow template.","frontmatter":{"title":"Minimal Config","description":"The config file paths, the shipped defaults, a working ticket source, and how to extend the workflow template."},"headers":[],"relativePath":"getting-started/minimal-config.md","filePath":"getting-started/minimal-config.md"}'),n={name:"getting-started/minimal-config.md"};function o(l,e,h,d,r,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="minimal-config" tabindex="-1">Minimal Config <a class="header-anchor" href="#minimal-config" aria-label="Permalink to &quot;Minimal Config&quot;">​</a></h1><h2 id="the-config-file" tabindex="-1">The Config file <a class="header-anchor" href="#the-config-file" aria-label="Permalink to &quot;The Config file&quot;">​</a></h2><p>The config lives at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.config/my-little-software-factory/config.toml</span></span></code></pre></div><p>or at the path the <code>--config</code> flag names:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-little-software-factory</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/config.toml</span></span></code></pre></div><p>The state file lives at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.local/state/my-little-software-factory/state.sqlite</span></span></code></pre></div><p>or at the path <code>$XDG_STATE_HOME/my-little-software-factory/state.sqlite</code> when the environment sets it, or at the path the <code>state-file</code> key names when the config sets one.</p><p>The shipped Default configuration carries a working control plane and the parts it cannot know about your machine: no ticket sources, no repository mappings, and no <code>state-file</code> key. Everything else is on: the <code>pi</code>, <code>codex</code>, and <code>claude</code> agent types, the four workflow task types, the three security task types, the states of the label workflow plus one state per security source kind, and one <code>consult</code> Consultation type that passes your input straight through. The <a href="./../configuration/#key-reference">configuration key reference</a> names every key, its default, and what it does.</p><h2 id="upgrading-an-older-install" tabindex="-1">Upgrading an older install <a class="header-anchor" href="#upgrading-an-older-install" aria-label="Permalink to &quot;Upgrading an older install&quot;">​</a></h2><p>An install whose Config file still carries <code>[[task-rules]]</code> or <code>workflows</code> is rewritten once, at load (ADR 0027). The rules become states, an edge whose target one state offers becomes that task type&#39;s transition, the shipped task templates are replaced when they match the old seed exactly, and the shipped machine&#39;s parking state comes over with them. The rewrite is validated before anything is written, and it leaves two files beside the config: the pre-migration <code>config.toml.bak</code>, and <code>config.toml.migration-report.md</code>, which names every state, transition, dropped edge, and untouched template. A failure there stops the control plane with your file unchanged. The start line states the migration once, and a config that still carries an old key after it is one readable config error.</p><h2 id="add-a-ticket-source" tabindex="-1">Add a ticket source <a class="header-anchor" href="#add-a-ticket-source" aria-label="Permalink to &quot;Add a ticket source&quot;">​</a></h2><p>The Default configuration holds a commented-out source block where you add your own. Unmark it and edit the <code>repositories</code> list to your <code>owner/name</code> values:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;issues&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;github-issues&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refresh-interval-seconds = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repositories = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;owner/name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;owner/other&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The <code>name</code> is what the interface shows. The <code>kind</code> is <code>github-issues</code> or <code>github-pull-requests</code>, or one of the security feed kinds <code>github-security-advisories</code>, <code>github-dependabot-alerts</code>, and <code>github-secret-scanning-alerts</code>: the three kinds read the repository security tab, each item appears as one ticket, and the shipped machine already routes each kind to its resolve task type. The security feed kinds take no <code>filter</code>. The <code>refresh-interval-seconds</code> sets how often the control plane refreshes the source. The source reads the labels on each ticket; <a href="./../development/labels.html">the ticket labels</a> name what each label means to the control plane.</p><p>Repository checkout paths live in the <code>repos</code> table, one key per <code>owner/name</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">repos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;owner/name&quot; = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/src/name&quot;</span></span></code></pre></div><h2 id="extend-the-workflow-machine" tabindex="-1">Extend the workflow machine <a class="header-anchor" href="#extend-the-workflow-machine" aria-label="Permalink to &quot;Extend the workflow machine&quot;">​</a></h2><p>The states and the task-type transitions of the Default configuration are the workflow machine, and the file marks them as meant to be extended. The plane owns the workflow labels: it reads a ticket&#39;s position from the labels it carries, and it writes those labels itself when a task completes. The agents write no workflow labels, so a prompt template names none. The machine carries the four task types <code>implement</code>, <code>review</code>, <code>rework</code>, and <code>merge</code>, plus the three security task types <code>resolve-security-advisory</code>, <code>resolve-dependabot-alert</code>, and <code>resolve-secret-scanning-alert</code>.</p><p>The shipped machine is the label workflow. Its states are ordered and the first match wins:</p><table tabindex="0"><thead><tr><th>State</th><th>When</th><th>Task type</th></tr></thead><tbody><tr><td>1</td><td>An open issue carries the <code>ready-for-agent</code> label.</td><td><code>implement</code></td></tr><tr><td>2</td><td>A pull request carries the <code>needs-work</code> label.</td><td><code>rework</code></td></tr><tr><td>3</td><td>A pull request carries the <code>ready-for-review</code> label.</td><td><code>review</code></td></tr><tr><td>4</td><td>A pull request carries the <code>ready-to-ship</code> label.</td><td><code>merge</code></td></tr><tr><td>5</td><td>A ticket comes from a <code>github-security-advisories</code> source.</td><td><code>resolve-security-advisory</code></td></tr><tr><td>6</td><td>A ticket comes from a <code>github-dependabot-alerts</code> source.</td><td><code>resolve-dependabot-alert</code></td></tr><tr><td>7</td><td>A ticket comes from a <code>github-secret-scanning-alerts</code> source.</td><td><code>resolve-secret-scanning-alert</code></td></tr><tr><td>8</td><td>A pull request carries none of them.</td><td>none: the plane waits</td></tr></tbody></table><p>A state with no <code>task-type</code> is a parking state: the plane suggests nothing for a ticket that sits there, and a label write is the only thing that moves it. The last state is what holds a pull request someone else opened until a transition or a human puts it in the machine. A completed security turn rests its ticket on the same-type hold while the finding still lists upstream.</p><p>A <code>[task-types.&lt;name&gt;.transition]</code> table is what happens when a turn of that type completes: the plane writes the transition&#39;s labels on the ticket, and on the pull request the ticket links, and the machine re-derives every position from the labels it wrote. The write is a convergence of the machine&#39;s own labels: it adds the named facts and removes the labels the machine&#39;s writes name that the facts do not, and a scoping label a state match names but no transition writes - such as a <code>labels-all</code> gate - is left alone. The labels your machine writes must exist in the repository before a fire can succeed: a write that names a missing label fails, and <a href="./../development/labels.html">the ticket labels page</a> carries the one command that creates them. The shipped transitions move an implemented issue&#39;s pull request to <code>ready-for-review</code>, decide a review by its score against <code>score-threshold</code> (90 in the shipped machine, and the one place that number lives), send a blocked merge back to <code>needs-work</code>, and move an opened security fix&#39;s pull request to <code>ready-for-review</code> and into its review position.</p><p>Add your own task type with a <code>[task-types.&lt;name&gt;]</code> table. The <code>template</code> carries the prompt body, and the <code>{placeholders}</code> name the ticket facts the control plane fills in. Add a state that routes a ticket to it, and a transition on the type that completes it:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task-types</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my-type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;My prompt for {title}.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task-types</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my-type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">transition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ticket-facts = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pull-request-facts = []</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">states</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mine&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">task-type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-type&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">states</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">match</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">source-kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;github-pull-request&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">labels-any = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-label&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>A ticket no state matches takes the <code>default-task-type</code>, and that task type&#39;s transition fires the same way: the completion behavior follows the task type to whatever ticket it runs on.</p><p>The writes run as the source&#39;s own authentication: the <code>[sources.auth]</code> table of the source the item lists on is the credential the plane&#39;s <code>gh edit</code> carries, so the plane&#39;s writes and its reads come from the same account.</p>`,28)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
